func testLLMConversationToManyAddOpConversationLLMChatMessages(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a LLMConversation
	var b, c, d, e LLMChatMessage

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, llmConversationDBTypes, false, strmangle.SetComplement(llmConversationPrimaryKeyColumns, llmConversationColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*LLMChatMessage{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, llmChatMessageDBTypes, false, strmangle.SetComplement(llmChatMessagePrimaryKeyColumns, llmChatMessageColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*LLMChatMessage{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddConversationLLMChatMessages(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.ID != first.ConversationID {
			t.Error("foreign key was wrong value", a.ID, first.ConversationID)
		}
		if a.ID != second.ConversationID {
			t.Error("foreign key was wrong value", a.ID, second.ConversationID)
		}

		if first.R.Conversation != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Conversation != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.ConversationLLMChatMessages[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.ConversationLLMChatMessages[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.ConversationLLMChatMessages().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

